// Checks that every source file we own carries the copyright header.
// Usage: node tools/check-headers.cjs [--fix]
// Exclusions (not ours or generated): node_modules, bin, obj, artifacts, dist, keys, payload, .git,
// Fixtures folders (test page fixtures), *.g.cs, *.g.i.cs, *.Designer.cs, AssemblyInfo.cs, files marked auto-generated,
// and every file type other than cs, xaml, js, cjs, ps1, py, wxs, csproj, props (JSON, HTML, images, docs, binaries).
'use strict';
const fs = require('fs');
const path = require('path');

const TEXT = 'Copyright (c) 2026 unlimitedera. MIT License. https://github.com/unlimitedera/NeoDM. Keep this notice; see NOTICE.';
const root = path.resolve(__dirname, '..');
const skipDirs = new Set(['node_modules', 'bin', 'obj', 'artifacts', 'dist', 'keys', 'payload', '.git', 'Fixtures', '.vs']);
const skipNames = /(\.g\.cs|\.g\.i\.cs|\.Designer\.cs)$|^AssemblyInfo\.cs$/;
const styles = { cs: 'slash', js: 'slash', cjs: 'slash', ps1: 'hash', py: 'hash', xaml: 'xml', wxs: 'xml', csproj: 'xml', props: 'xml' };

function walk(dir, out) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) { if (!skipDirs.has(e.name)) walk(path.join(dir, e.name), out); continue; }
    const ext = path.extname(e.name).slice(1).toLowerCase();
    if (!styles[ext] || skipNames.test(e.name)) continue;
    out.push(path.join(dir, e.name));
  }
  return out;
}

function line(style) {
  return style === 'slash' ? '// ' + TEXT : style === 'hash' ? '# ' + TEXT : '<!-- ' + TEXT + ' -->';
}

function hasHeader(text) { return text.slice(0, 600).includes(TEXT); }

function addHeader(file, text) {
  const style = styles[path.extname(file).slice(1).toLowerCase()];
  let bom = '';
  if (text.charCodeAt(0) === 0xFEFF) { bom = '\uFEFF'; text = text.slice(1); }
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  let head = '';
  let rest = text;
  // keep a shebang, python coding line or XML declaration first
  let m = null;
  if (style === 'xml') m = /^<\?xml[^>]*\?>[ \t]*\r?\n?/.exec(rest);
  else m = /^#!.*\r?\n/.exec(rest);
  if (m) { head = m[0].endsWith('\n') ? m[0] : m[0] + eol; rest = rest.slice(m[0].length); }
  return bom + head + line(style) + eol + rest;
}

const fix = process.argv.includes('--fix');
const files = walk(root, []);
const missing = [];
let skippedGenerated = 0;
for (const f of files) {
  const text = fs.readFileSync(f, 'utf8');
  if (/<auto-generated/.test(text.slice(0, 400))) { skippedGenerated++; continue; }
  if (hasHeader(text)) continue;
  if (fix) fs.writeFileSync(f, addHeader(f, text), 'utf8');
  else missing.push(path.relative(root, f).replace(/\\/g, '/'));
}
if (fix) { console.log('header added where missing; checked ' + files.length + ' files'); process.exit(0); }
console.log('Header check: ' + files.length + ' owned files, ' + skippedGenerated + ' generated skipped, ' + missing.length + ' missing');
if (missing.length) { missing.slice(0, 40).forEach(m => console.log('  MISSING ' + m)); process.exit(1); }
